import{_ as r,o as a,c as n,ag as t}from"./chunks/framework.C15dTZqp.js";const m=JSON.parse(`{"title":"Exercice : de l'interview au PRD","description":"","frontmatter":{},"headers":[],"relativePath":"handout-07-exercice-prd.md","filePath":"handout-07-exercice-prd.md","handout":{"fichier":"handout-07-exercice-prd.md","markdown":"# Handout — Exercice : de l'interview au PRD\\n\\n**Speed training IA · Zenika · support d'exercice**\\n\\nInterview fictive, menée dans le cadre de la discovery « abandons de réservation sur mobile ». Utilisez ce compte-rendu pour faire générer un PRD en 6 rubriques (problème, objectif, user story, périmètre, hypothèses, critères de succès), puis relisez-le.\\n\\n**Participante** : Claire, 41 ans, cheffe de projet dans une entreprise de BTP. Voyage 2 à 3 fois par mois pour le travail, réserve presque toujours depuis son téléphone.\\n\\n**Contexte** : entretien de 30 minutes en visio, mené par la PO et le designer de l'équipe Réservation.\\n\\n---\\n\\n**« Racontez-moi la dernière fois que vous avez réservé un hôtel. »**\\n\\n> « Mardi dernier, dans le train. Je devais être à Lyon le lendemain pour un chantier. J'ai trouvé l'hôtel en deux minutes, ça c'est bien. Par contre au paiement… il a fallu ressaisir toute ma carte, alors que je réserve chez vous depuis des années. Dans le train, avec le réseau qui saute, la validation de la banque a expiré. J'ai dû tout recommencer. »\\n\\n**« Et ensuite, qu'avez-vous fait ? »**\\n\\n> « J'ai abandonné, honnêtement. J'ai réservé le soir depuis mon ordinateur à l'hôtel… enfin, chez moi. Mais le tarif avait augmenté de 15 euros. »\\n\\n**« Pourquoi pas tout de suite sur l'ordinateur ? »**\\n\\n> « Parce que je n'en ai pas dans le train. Et puis, je voulais régler ça tout de suite, sinon j'oublie. »\\n\\n**« Y a-t-il autre chose qui vous a gênée ? »**\\n\\n> « Au moment de payer, je ne savais plus si le tarif était annulable. Mes déplacements bougent souvent. C'était écrit quelque part plus haut, mais je n'avais pas envie de remonter. Ah, et je ne comprends jamais où mettre mon numéro de carte de fidélité. »\\n\\n**« Si vous pouviez changer une chose ? »**\\n\\n> « Payer avec la carte que vous avez déjà. Comme sur les sites de e-commerce. »\\n\\n---\\n\\n**Notes de l'équipe**\\n\\n- Elle a utilisé le mot « recommencer » trois fois.\\n- Elle n'a pas parlé du prix, sauf pour les 15 euros perdus.\\n- Elle réserve pour son entreprise mais paie avec sa carte personnelle, puis se fait rembourser.\\n"}}`),i={name:"handout-07-exercice-prd.md"};function s(o,e,u,l,p,d){return a(),n("div",null,[...e[0]||(e[0]=[t("",19)])])}const v=r(i,[["render",s]]);export{m as __pageData,v as default};
